b:if.b:template-skin:
/*    Layout editor (Bo   cu c)   MMO pro board    */
body#layout{
  background:
    radial-gradient(circle at 12% 0%, rgba(212,175,55,.08), transparent 34%),
    linear-gradient(180deg,#070b08 0%,#0a100d 100%)!important;
  border:1px solid #243328!important;
  color:#e8fff2!important;
  font-family:'Inter',system-ui,-apple-system,'Segoe UI',sans-serif!important;
  padding:18px!important;
  box-sizing:border-box!important;
}
body#layout::before{
  content:'MMO  \00b7   B\1ed1  c\1ee5 c theme';
  display:block;
  margin:0 0 14px;
  padding:10px 14px;
  border:1px solid rgba(212,175,55,.35);
  border-radius:12px;
  background:rgba(8,14,10,.92);
  color:#f3e2a8;
  font:700 13px/1.3 monospace;
  letter-spacing:.08em;
  text-transform:uppercase;
}
body#layout .qcx-signal-header,
body#layout .qcx-mac-topbar,
body#layout .qcx-site-footer,
body#layout .qcx-mobile-cta,
body#layout .qcx-scanline,
body#layout .qcx-backdrop,
body#layout .footer-navigation-bar,
body#layout #qcx-menu,
body#layout #qcx-menu-backdrop,
body#layout #qcx-mobile-search,
body#layout #qcx-native-tabbar{display:none!important}
body#layout header,
body#layout .main-container{display:block!important;width:100%!important;max-width:none!important;float:none!important;padding:0!important;margin:0!important}
/* Layout editor: float main left + Thanh be n right (Blogger strips grid-template-columns here). */
body#layout .main-wrapper{
  display:block!important;
  width:100%!important;
  max-width:none!important;
  float:none!important;
  padding:0!important;
  margin:0 0 14px!important;
  box-sizing:border-box!important;
  overflow:visible!important;
}
/* Layout editor: restore header/menu chrome so Edit/Delete are not clipped. */
body#layout header:not(.post-header),
body#layout header{
  display:block!important;
  height:auto!important;
  min-height:0!important;
  overflow:visible!important;
  position:static!important;
  z-index:auto!important;
  background:transparent!important;
  border:0!important;
}
body#layout .menu.section,
body#layout #menu.menu,
body#layout #menu{
  -webkit-transform:none!important;
  -ms-transform:none!important;
  transform:none!important;
  position:relative!important;
  top:auto!important;
  bottom:auto!important;
  left:auto!important;
  width:auto!important;
  min-height:92px!important;
  overflow:visible!important;
}
body#layout .widget .edit,
body#layout .widget a.edit,
body#layout span.widget-toolbar,
body#layout .layout-widget-state{
  display:inline-block!important;
  visibility:visible!important;
  opacity:1!important;
  pointer-events:auto!important;
}
/* Layout board: force native header/gadgets visible (live hide stays outside #layout). */
body#layout header:not(.post-header),
body#layout #header,
body#layout .header.section,
body#layout #header-wrapper,
body#layout .header-outer,
body#layout .header-inner{
  display:block!important;
  height:auto!important;
  min-height:0!important;
  overflow:visible!important;
  visibility:visible!important;
  opacity:1!important;
  position:static!important;
  z-index:auto!important;
}
body#layout .widget{
  display:block!important;
}
body#layout .widget .edit,
body#layout .widget a.edit,
body#layout .deletelink,
body#layout a.delete,
body#layout .add_widget{
  display:inline-block!important;
  visibility:visible!important;
  opacity:1!important;
  pointer-events:auto!important;
}
body#layout #brand,
body#layout #header,
body#layout #menu,
body#layout #homepage-widgets,
body#layout #main,
body#layout #below-main,
body#layout #sidebar,
body#layout #footer{
  display:block!important;
  float:none!important;
  clear:both!important;
  width:100%!important;
  min-height:92px!important;
  margin:0 0 14px!important;
  padding:14px!important;
  box-sizing:border-box!important;
  border:1px solid rgba(28,36,32,.18)!important;
  border-radius:14px!important;
  background:rgba(10,18,13,.96)!important;
  box-shadow:0 10px 28px rgba(0,0,0,.28)!important;
  position:relative!important;
}
body#layout #brand{border-color:rgba(212,175,55,.4)!important;background:linear-gradient(135deg,rgba(20,16,8,.98),rgba(8,12,9,.98))!important}
body#layout #header,body#layout #menu{width:calc(50% - 8px)!important;display:inline-block!important;vertical-align:top!important;clear:none!important}
body#layout #menu{margin-left:16px!important}
body#layout #main{
  float:left!important;
  clear:none!important;
  /* content-box in layout iframe: leave headroom for padding/border */
  width:60%!important;
  max-width:60%!important;
  min-height:220px!important;
  margin:0!important;
  padding:10px!important;
  border-color:rgba(28,36,32,.35)!important;
}
body#layout #sidebar{
  float:right!important;
  clear:none!important;
  width:35%!important;
  max-width:35%!important;
  min-height:220px!important;
  margin:0!important;
  padding:10px!important;
  border-color:rgba(212,175,55,.45)!important;
}
body#layout #below-main{
  float:none!important;
  clear:both!important;
  width:100%!important;
  margin:14px 0 0!important;
}
body#layout .main-wrapper::after{
  content:''!important;
  display:table!important;
  clear:both!important;
}
body#layout .widget{
  position:static!important;
  opacity:1!important;
  visibility:visible!important;
  margin:8px 0!important;
  padding:12px!important;
  border:1px solid rgba(255,255,255,.08)!important;
  border-radius:10px!important;
  background:rgba(255,255,255,.03)!important;
  color:#e8fff2!important;
}
body#layout .widget > h2,
body#layout .widget .title{color:#20d99a!important;font:700 12px/1.3 monospace!important;margin:0 0 8px!important}
body#layout .qcx-layout-brand{
  display:flex!important;
  align-items:center!important;
  gap:14px!important;
}
body#layout .qcx-layout-brand img{
  width:72px!important;height:72px!important;border-radius:16px!important;
  border:1px solid rgba(212,175,55,.45)!important;object-fit:cover!important;background:#000!important;
}
body#layout .qcx-layout-brand strong{display:block;color:#fff;font-size:18px;letter-spacing:.04em}
body#layout .qcx-layout-brand span{display:block;color:rgba(230,245,236,.7);font-size:12px;margin-top:4px}

b:if.script:
//
(function(){
  var HOME_VI_TITLE = "MMO TEAM \u2013 C\u00f4ng c\u1ee5 AI \u00b7 H\u01b0\u1edbng d\u1eabn th\u1ef1c chi\u1ebfn \u00b7 T\u00e0i nguy\u00ean mi\u1ec5n ph\u00ed";
  if (!document.title || /[\u0393\u251c\u255f\u252c\u255e\u2591\u00df\u2551\u00bd\u2592\u2510\u2524\u00d1\u00a1]/.test(document.title)) {
    if (location.pathname === "/" || location.pathname === "/index.html") {
      document.title = HOME_VI_TITLE;
    } else {
      document.title = (document.title || "").replace(/MMO TEAM.*$/i, "MMO TEAM");
    }
  }
})();
//

(function(){
  var id = '';
  if (!id) return;
  window.__qcxPostId = String(id);
  var path = (location.pathname || '').replace(/\/$/, '');
  function isReloadNav(){
    try {
      var nav = performance.getEntriesByType && performance.getEntriesByType('navigation')[0];
      if (nav && nav.type) return nav.type === 'reload';
    } catch (e1) {}
    try { return performance.navigation && performance.navigation.type === 1; } catch (e2) {}
    return false;
  }
  window.__qcxPostPrefetch = fetch('/feeds/posts/default/' + id + '?alt=json', {
    credentials: 'same-origin',
    cache: 'no-store'
  }).then(function(r){ return r.json(); }).then(function(full){
    try {
      var entry = full && full.entry;
      /* F5: do not repopulate sessionStorage — races rescue reload skip and causes old→new flash. */
      if (entry && path && !isReloadNav()) {
        sessionStorage.setItem('qcx:post:' + path, JSON.stringify({ t: Date.now(), d: entry }));
      }
    } catch (ignore) {}
    return full;
  });
})();

