.dd-menu>li>span{display:-ms-flexbox;display:-webkit-flex;display:flex;-webkit-align-items:center;align-items:center}
.dd-menu svg{margin-right:20px}
.theme-button{position:relative;display:inline-block;text-align:center;font-size:.9rem;white-space:nowrap;height:32px;line-height:30px}
.theme-button:not(.loading){border:1px solid;padding:0 10px;-webkit-border-radius:3px;-moz-border-radius:3px;border-radius:3px;-webkit-transition:all .2s;transition:all .2s}
.theme-button:not(:hover):not(:focus):not(.blue):not(.mess):not(.loading):not(.submit){background:#fff;border-color:hsl(0,0%,53.3%);color:rgba(0,0,0,0.87)}.theme-button.loading{text-indent:-9999px}
.theme-button.loading:before{content:'';box-sizing:border-box;position:absolute;top:calc(50% - 15px);left:calc(50% - 15px);width:30px;height:30px;border-radius:50%;border:2px solid #03a9f4;border-right-color:transparent;animation:spinner .9s linear infinite;-webkit-animation:spinner .9s ease-in-out infinite}
.theme-button:not(.loading):not(.blue):not(.mess):not(.disabled):hover,.theme-button:not(.loading):not(.blue):not(.mess):not(.disabled):focus{background:#008db8;border-color:#008db8;color:#fff}
.theme-button:not(button){min-width:70px}button.theme-button:not(.blue){min-width:80px}
.theme-button.submit{background:#008db8;border-color:#008db8;color:#fff}
.theme-button.blue{min-width:60px;background:#03a5fa;border-color:#00aeef;color:#fff}
.theme-button.mess{min-width:60px;background:#0084FF;border-color:#00aeef;color:#fff}
input.theme-button{-webkit-appearance:button}button.theme-button:focus{outline:none!important}
.main-container{max-width:1920px;margin:0 auto;display:-ms-flexbox;display:-webkit-flex;display:flex;-ms-flex-flow:row wrap;flex-flow:row wrap}
.theme-button.disabled{background:#fff;border-color:hsl(0,0%,53.3%);color:rgba(0,0,0,0.87);pointer-events:none;opacity:.7}
.zb-logo-zalo,.ms-logo-facebook{display:inline-block;vertical-align:middle}
