/* MMO &#8212; dark theme layout v3 */
:root {
  color-scheme: dark;
  --bg:       #0a0f0a;
  --bg-2:     #0d150e;
  --fg:       #e6f5ec;
  --fg-dim:   #8aa596;
  --line:     #1d2a1f;
  --accent:   #4caf82;
  --accent-2: #b48cff;
  --danger:   #ff5470;
  --card:     #0e170f;
  --mono: 'JetBrains Mono', ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
  --sans: 'Inter', system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --focus: #4caf82;
}
a:focus-visible,button:focus-visible,input:focus-visible,[tabindex]:focus-visible,.qcx-cta-btn:focus-visible,.qcx-signal-status:focus-visible,.qcx-signal-x:focus-visible,.card-header>a:focus-visible,.web-search input:focus-visible,.web-search button:focus-visible,.scroll--top:focus-visible{
  outline:2px solid var(--focus)!important;
  outline-offset:2px!important;
}
@media (prefers-reduced-motion: reduce){
  .qcx-scanline,.qcx-signal-dot,.qcx-avatar::after{animation:none!important}
  html{scroll-behavior:auto!important}
}
.qcx-skip-link{
  position:absolute;left:12px;top:12px;z-index:10000;
  padding:10px 14px;border-radius:10px;
  background:#141a16;color:#e8efe9;font:700 12px var(--mono);
  transform:translateY(-160%);
}
.qcx-skip-link:focus,.qcx-skip-link:focus-visible{transform:translateY(0);outline:2px solid #fff;outline-offset:2px}
/* &#226;&#8221;&#8364;&#226;&#8221;&#8364; BASE FONT INHERITANCE &#226;&#8364;&#8221; replaces 80+ individual font-family declarations &#226;&#8221;&#8364;&#226;&#8221;&#8364; */
/* All custom elements inherit mono font from body (set above) */
[class^="qcx-"], [class*=" qcx-"],
.card, .card-content, .card-footer,
.keywords a { font-family: var(--mono); }

/* --- Grid Backdrop + Scanline &#8212; EXACT from embed.html lines 94-112 --- */
.qcx-backdrop {
  position: fixed; inset: 0; z-index: 0; pointer-events: none;
  background:
    radial-gradient(1200px 600px at 80% -10%, rgba(28,36,32,.08), transparent 60%),
    radial-gradient(900px 500px at -10% 30%, rgba(180,140,255,.09), transparent 60%),
    linear-gradient(var(--line) 1px, transparent 1px) 0 0/48px 48px,
    linear-gradient(90deg, var(--line) 1px, transparent 1px) 0 0/48px 48px,
    var(--bg);
  mask-image: radial-gradient(ellipse at 50% 20%, black 40%, transparent 85%);
  -webkit-mask-image: radial-gradient(ellipse at 50% 20%, black 40%, transparent 85%);
}
.qcx-scanline {
  position: fixed; inset: 0; z-index: 1; pointer-events: none;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0 3px,
    rgba(255,255,255,.012) 3px 4px
  );
  mix-blend-mode: overlay;
}

/* ==================================================
   BASE BODY + TYPOGRAPHY
================================================== */
body {
  background: var(--bg) !important;
  color: var(--fg) !important;
  font-family: var(--mono) !important;
  line-height: 1.55 !important;
  -webkit-font-smoothing: antialiased;
  padding-top: 0 !important;
}
a { color: inherit; }
/* Accent is dark brand fill &#8212; global link hover must stay readable on dark UI. */
a:hover { color: var(--fg, #e8efe9); }
/* Form/button elements: inherit mono font (browser UA overrides otherwise) */
button, input, select, textarea { font-family: inherit; }

/* ==================================================
   REFERENCE SIGNAL HEADER &#8212; static, no topbar
================================================== */
.qcx-signal-header {
  position: relative;
  z-index: 2;
  width: 100%;
  height: 56px;
  box-sizing: border-box;
}
.qcx-signal-inner {
  position: relative;
  width: calc(100% - 48px);
  max-width: 1120px;
  height: 100%;
  margin: 0 auto;
  padding-top: 8px;
  box-sizing: border-box;
}
.qcx-signal-inner::after {
  content: '';
  position: absolute;
  top: 52px;
  left: 0;
  right: 0;
  border-top: 1px dashed rgba(28,36,32,.11);
}
.qcx-signal-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 41px;
  font-family: var(--mono, 'JetBrains Mono', monospace);
}
.qcx-signal-status {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: rgba(190,211,198,.72);
  font-size: 13px;
  line-height: 1;
  letter-spacing: .02em;
  text-decoration: none !important;
  white-space: nowrap;
  transition: color .2s ease;
}
.qcx-signal-status:hover,
.qcx-signal-status:focus-visible {
  color: #effff5;
  text-decoration: none !important;
}
.qcx-signal-status:focus-visible {
  border-radius: 4px;
  outline: 2px solid rgba(28,36,32,.75);
  outline-offset: 4px;
}
.qcx-signal-dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: #20d99a;
  box-shadow: 0 0 13px rgba(28,36,32,.68);
  flex: 0 0 11px;
  animation: qcxSignalPulse 2.4s ease-in-out infinite;
}
@keyframes qcxSignalPulse {
  0%, 100% { opacity: 1; box-shadow: 0 0 13px rgba(28,36,32,.68); }
  50% { opacity: .48; box-shadow: 0 0 5px rgba(28,36,32,.38); }
}
.qcx-signal-x {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  min-height: 36px;
  padding: 0 14px;
  box-sizing: border-box;
  border: 1px solid rgba(134,199,158,.18);
  border-radius: 999px;
  background: rgba(6,15,10,.34);
  color: rgba(226,239,230,.92) !important;
  -webkit-text-fill-color: rgba(226,239,230,.92);
  font-size: 13px;
  font-weight: 600;
  line-height: 1;
  letter-spacing: -.01em;
  text-decoration: none !important;
  white-space: nowrap;
  overflow: hidden;
  transition: color .2s ease, border-color .2s ease, background .2s ease, box-shadow .2s ease;
}
.qcx-signal-x-label {
  display: inline-flex;
  align-items: center;
  line-height: 1;
}
.qcx-signal-x-arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 12px;
  height: 12px;
  font-size: 12px;
  line-height: 1;
  opacity: .85;
  transform: translateY(0.5px);
}
.qcx-signal-x:hover,
.qcx-signal-x:focus-visible {
  color: #effff5 !important;
  -webkit-text-fill-color: #effff5;
  border-color: rgba(28,36,32,.42);
  background: rgba(28,36,32,.07);
  box-shadow: 0 0 18px rgba(28,36,32,.09);
}
@media (max-width: 860px) {
  /* Mobile: b&#7887; chrome "pro" &#8212; d&#249;ng tab bar native */
  .qcx-signal-header { display: none !important; height: 0 !important; }
}


/* ==================================================
   HEADER &#8212; &#7849;n chrome Blogger (<header> tr&#7855;ng fixed),
   nh&#432;ng GI&#7918; header.post-header (ti&#234;u &#273;&#7873; b&#224;i).
================================================== */
header:not(.post-header),
#header,
#header-wrapper,
header.header,
.header.section,
.header-outer,
.header-inner,
b\:section[id='header'],
b\:section[name='header'] {
  display: none !important;
}
/* Kill leftover fixed white site-header rules on any non-article header. */
header:not(.post-header) {
  position: static !important;
  height: 0 !important;
  overflow: hidden !important;
  background: transparent !important;
  border: 0 !important;
  z-index: -1 !important;
}
/* Article title block must stay visible on single posts. */
header.post-header,
.post-item > header.post-header,
.the-article > header.post-header,
.qcx-rescue-single header.post-header {
  display: block !important;
  position: relative !important;
  top: auto !important;
  left: auto !important;
  right: auto !important;
  height: auto !important;
  z-index: auto !important;
  background: transparent !important;
  border: 0 !important;
}

/* ==================================================
   FIX KHO&#7842;NG TR&#7854;NG D&#431;&#7898;I FOOTER
   div.bottom l&#224; Blogger "bottom" section render sau </footer>
   Ch&#7913;a widget Blogger r&#7895;ng c&#243; th&#7875; t&#7841;o kho&#7843;ng tr&#7855;ng cu&#7889;i trang
================================================== */
div.bottom,
.bottom-wrapper,
[class='bottom'] {
  display: none !important;
  height: 0 !important;
  overflow: hidden !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Overlay hidden &#8212; &#273;&#7843;m b&#7843;o kh&#244;ng chi&#7871;m space */
.overlay,
.overlay.hidden,
div.overlay {
  display: none !important;
  height: 0 !important;
  overflow: hidden !important;
}

/* scroll--top (native, replaced b&#7903;i custom JS) */
.scroll--top {
  display: none !important;
}

/* ==================================================
   &#7848;N SHARE MENU (n&#7873;n tr&#7855;ng n&#7893;i tr&#234;n dark theme)
   .share-menu = Blogger native share bottom-sheet
   Hi&#7879;n ra khi b&#7845;m n&#250;t share tr&#234;n b&#224;i vi&#7871;t
================================================== */
.footer-navigation-bar .share-menu,
.footer-navigation-bar .share-menu.visible,
.share-menu {
  display: none !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

/* &#7848;n n&#250;t share nh&#7887; tr&#234;n card + b&#224;i vi&#7871;t */
.post-share,
.card-content .share,
[aria-label='Share'],
[title='Share'],
button.share,
a.share {
  display: none !important;
}

/* AN // available meta text */
.qcx-meta {
  display: none;
}

/* ==================================================
   CONTENT WIDTH &#8212; match QCXINT .wrap
   .wrap { max-width:1120px; margin:0 auto; padding:32px 24px 96px }
   Applied to all injected sections so they align with footer
================================================== */
.qcx-hero,
.qcx-section-head,
.qcx-rule {
  max-width: 1120px;
  margin-left: auto;
  margin-right: auto;
  padding-left: 24px;
  padding-right: 24px;
  box-sizing: border-box;
}

/* ==================================================
   HERO SECTION &#8212; 2-column: text left, avatar right
================================================== */
.qcx-hero {
  padding: 24px 0 36px;
  display: grid;
  grid-template-columns: 1.45fr 0.9fr;
  gap: 44px;
  align-items: center;
  position: relative;
  z-index: 2;
}
.qcx-hero-inner {
  width: 100%;
  min-width: 0;
}
.qcx-kicker {
  font-size: 11px;
  color: var(--accent);
  letter-spacing: .18em;
  text-transform: uppercase;
  margin-bottom: 16px;
  opacity: .8;
}

/* &#9472;&#9472; TITLE: solid color + neon glow (fixes Vietnamese diacritics)
   background-clip:text clips combining tone marks &#8594; marks go invisible
   Solid color + text-shadow preserves all d&#7845;u h&#7887;i/s&#7855;c/huy&#7873;n/ng&#227;/n&#7863;ng &#9472;&#9472; */
.qcx-hero-title {
  font-size: clamp(48px, 7vw, 86px);
  line-height: 1.05;
  letter-spacing: 0.04em;
  margin: 0 0 4px;
  font-weight: 700;
  color: #b8d4c0;              /* sampled from screenshot: muted mint-green */
  background: none;
  -webkit-background-clip: unset;
  background-clip: unset;
  -webkit-text-fill-color: unset;
  text-shadow:
    0 2px 6px rgba(0,0,0,.85),
    0 0 60px rgba(28,36,32,.06);
  border-bottom: none;
  font-family: var(--mono);
  text-transform: uppercase;
  overflow: visible;
  padding-top: 0.08em;
  white-space: nowrap;
}
/* Accent divider line */
.qcx-hero-divider {
  width: 48px;
  height: 2px;
  background: var(--accent);
  margin: 0 0 4px;
  border-radius: 1px;
  box-shadow: 0 0 8px rgba(28,36,32,.5);
}
.qcx-bio {
  font-size: 15px;
  color: var(--fg-dim);
  white-space: normal;
  max-width: 580px;
  border-left: 2px solid rgba(28,36,32,.3);
  padding-left: 18px;
  line-height: 2.0;
  margin: 0 0 28px;
}
/* Tag line */
.qcx-tags {
  display: inline-block;
  font-size: 10px;
  letter-spacing: .18em;
  color: var(--accent);
  font-weight: 700;
  text-transform: uppercase;
  opacity: .95;
  margin: 2px 0;
}
/* CTA buttons */
.qcx-hero-cta {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 4px;
}
.qcx-cta-btn {
  font-size: 12px;
  letter-spacing: .08em;
  padding: 9px 20px;
  border-radius: 6px;
  background: var(--accent);
  color: #000;
  font-weight: 700;
  text-decoration: none;
  transition: background-color .15s, border-color .15s, color .15s, transform .15s, box-shadow .15s;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.qcx-cta-btn:hover { background: #1c2420 !important; color: #e8efe9 !important; transform: translateY(-1px); box-shadow: 0 8px 24px rgba(28,36,32,.18); }
.qcx-cta-outline {
  background: rgba(28,36,32,.09);
  border: 1px solid rgba(232,239,233,.28);
  color: #eafff4;
}
.qcx-cta-outline:hover { background: #1c2420 !important; border-color: #e8efe9 !important; color: #e8efe9 !important; }
/* Hero CTA: mint primary + ghost Telegram (beat body:not(#layout) skin) */
body:not(#layout) .qcx-hero-cta.qcx-hero-cta--pro .qcx-cta-btn:not(.qcx-cta-outline),
body:not(#layout) .qcx-hero-cta .qcx-cta-btn:not(.qcx-cta-outline),
.qcx-hero-cta.qcx-hero-cta--pro .qcx-cta-btn:not(.qcx-cta-outline),
.qcx-hero-cta .qcx-cta-btn:not(.qcx-cta-outline) {
  background: linear-gradient(180deg, #34e6a0 0%, #1fd68a 100%) !important;
  color: #06140e !important;
  -webkit-text-fill-color: #06140e !important;
  border: 1px solid rgba(0,0,0,.18) !important;
  box-shadow: 0 1px 0 rgba(255,255,255,.28) inset, 0 10px 28px rgba(0,240,163,.22) !important;
  line-height: 1.25 !important;
  overflow: visible !important;
}
body:not(#layout) .qcx-hero-cta.qcx-hero-cta--pro .qcx-cta-btn:not(.qcx-cta-outline):hover,
body:not(#layout) .qcx-hero-cta .qcx-cta-btn:not(.qcx-cta-outline):hover,
.qcx-hero-cta.qcx-hero-cta--pro .qcx-cta-btn:not(.qcx-cta-outline):hover,
.qcx-hero-cta .qcx-cta-btn:not(.qcx-cta-outline):hover {
  background: linear-gradient(180deg, #4af0b0 0%, #28d28c 100%) !important;
  color: #04100b !important;
  -webkit-text-fill-color: #04100b !important;
  transform: translateY(-1px);
  box-shadow: 0 1px 0 rgba(255,255,255,.34) inset, 0 14px 34px rgba(0,240,163,.3) !important;
}
body:not(#layout) .qcx-hero-cta.qcx-hero-cta--pro .qcx-cta-outline,
body:not(#layout) .qcx-hero-cta .qcx-cta-outline,
.qcx-hero-cta.qcx-hero-cta--pro .qcx-cta-outline,
.qcx-hero-cta .qcx-cta-outline {
  border: 1px solid rgba(0,240,163,.28) !important;
  color: #e8fff2 !important;
  -webkit-text-fill-color: #e8fff2 !important;
  background: rgba(255,255,255,.03) !important;
  box-shadow: none !important;
  line-height: 1.25 !important;
  overflow: visible !important;
}
body:not(#layout) .qcx-hero-cta.qcx-hero-cta--pro .qcx-cta-outline:hover,
body:not(#layout) .qcx-hero-cta .qcx-cta-outline:hover,
.qcx-hero-cta.qcx-hero-cta--pro .qcx-cta-outline:hover,
.qcx-hero-cta .qcx-cta-outline:hover {
  background: rgba(0,240,163,.08) !important;
  border-color: rgba(0,240,163,.5) !important;
  color: #fff !important;
  -webkit-text-fill-color: #fff !important;
}
body:not(#layout) .qcx-cta-ico,
.qcx-cta-ico {
  display: inline-flex !important;
  width: 16px !important;
  height: 16px !important;
  flex: 0 0 auto !important;
}
body:not(#layout) .qcx-cta-ico svg,
.qcx-cta-ico svg {
  display: block !important;
  width: 16px !important;
  height: 16px !important;
}
/* Compact layout &#8212; keep original hero scale, only trim outer chrome */
.qcx-hero {
  padding-top: 20px !important;
  padding-bottom: 16px !important;
  gap: 28px !important;
  align-items: center !important;
}
.qcx-section-head {
  margin-top: 8px !important;
  margin-bottom: 8px !important;
}
.qcx-subscribe-card {
  margin: 36px auto 24px !important;
  width: calc(100% - 32px) !important;
  max-width: 1120px !important;
  contain: layout !important;
  min-height: 120px !important;
}
footer.footer {
  min-height: 0 !important;
  padding: 0 0 28px !important;
  margin: 0 !important;
}
.scroll--top {
  right: 16px !important;
  bottom: 16px !important;
}
@media (max-width: 860px) {
  /* Native mobile hero &#8212; avatar + title/bio, CTA full-width d&#432;&#7899;i */
  .qcx-hero {
    display: grid !important;
    grid-template-columns: 80px minmax(0, 1fr) !important;
    grid-template-areas: "avatar title" "avatar bio" "cta cta" !important;
    align-items: center !important;
    /* Match card column: no extra side inset vs .all_posts cards */
    width: 100% !important;
    max-width: none !important;
    margin-left: 0 !important;
    margin-right: 0 !important;
    padding: 10px 0 12px !important;
    padding-left: 0 !important;
    padding-right: 0 !important;
    gap: 4px 16px !important;
    row-gap: 6px !important;
    box-sizing: border-box !important;
  }
  .qcx-hero-inner { display: contents !important; }
  .qcx-avatar-wrap {
    grid-area: avatar !important;
    order: -1 !important;
    display: flex !important;
    justify-content: flex-start !important;
    align-self: center !important;
    margin: 0 !important;
  }
  .qcx-avatar {
    width: 80px !important;
    height: 80px !important;
    min-width: 80px !important;
    border-radius: 12px !important;
    box-shadow: none !important;
  }
  .qcx-avatar-mark > span { font-size: 16px !important; line-height: 1 !important; }
  .qcx-avatar-tag,
  .qcx-avatar::after,
  .qcx-kicker,
  .qcx-hero-divider { display: none !important; }
  .qcx-hero-title {
    grid-area: title !important;
    font-size: 17px !important;
    line-height: 1.2 !important;
    letter-spacing: .02em !important;
    margin: 0 !important;
    text-shadow: none !important;
    align-self: end !important;
    white-space: normal !important;
  }
  .qcx-bio {
    grid-area: bio !important;
    font-size: 12px !important;
    line-height: 1.35 !important;
    max-width: none !important;
    padding-left: 0 !important;
    border-left: 0 !important;
    margin: 0 !important;
    display: -webkit-box !important;
    -webkit-line-clamp: 2 !important;
    -webkit-box-orient: vertical !important;
    overflow: hidden !important;
    color: rgba(190,211,198,.78) !important;
    align-self: start !important;
  }
  .qcx-hero-cta,
  .qcx-hero-cta.qcx-hero-cta--pro {
    grid-area: cta !important;
    display: flex !important;
    flex-direction: column !important;
    flex-wrap: nowrap !important;
    gap: 8px !important;
    margin: 10px 0 0 !important;
    width: 100% !important;
    max-width: none !important;
  }
  .qcx-hero-cta .qcx-cta-btn {
    box-sizing: border-box !important;
    flex: none !important;
    width: 100% !important;
    min-width: 0 !important;
    height: 48px !important;
    min-height: 48px !important;
    max-height: 48px !important;
    padding: 0 16px !important;
    font-size: 14px !important;
    letter-spacing: -.01em !important;
    line-height: 1 !important;
    justify-content: center !important;
    align-items: center !important;
    border-radius: 12px !important;
    white-space: nowrap !important;
    overflow: hidden !important;
  }
  /* Secondary matches primary height &#8212; ghost, not a short text-link */
  .qcx-hero-cta .qcx-cta-outline {
    height: 48px !important;
    min-height: 48px !important;
    max-height: 48px !important;
    background: rgba(255,255,255,.03) !important;
    border: 1px solid rgba(0,240,163,.28) !important;
    color: #e8fff2 !important;
    -webkit-text-fill-color: #e8fff2 !important;
    font-weight: 650 !important;
    box-shadow: none !important;
  }
  .qcx-hero-cta .qcx-cta-outline:hover {
    background: rgba(0,240,163,.08) !important;
    border-color: rgba(0,240,163,.5) !important;
    color: #fff !important;
    -webkit-text-fill-color: #fff !important;
    transform: none !important;
    box-shadow: none !important;
  }
  .qcx-section-head {
    margin: 6px 0 2px !important;
    padding: 0 !important;
  }
  .qcx-section-head h2 { font-size: 15px !important; margin: 0 !important; }
  .qcx-rule { margin: 0 0 8px !important; }
  .qcx-inline-search {
    min-height: 44px !important;
    margin: 0 0 14px !important;
    padding: 0 14px !important;
    border-radius: 12px !important;
    max-width: none !important;
  }
  .qcx-inline-search .qcx-search-text {
    font-size: 14px !important;
  }
  .qcx-inline-search .qcx-search-shortcut { display: none !important; }
  .qcx-subscribe-card {
    margin: 14px auto 10px !important;
    padding: 12px !important;
  }
  .qcx-subscribe-card .qcx-sc-title { font-size: 14px !important; margin-bottom: 4px !important; }
  .qcx-subscribe-card .qcx-sc-desc { font-size: 11px !important; }
  .qcx-subscribe-card .qcx-sc-actions {
    width: 100%;
    display: flex !important;
    flex-direction: column !important;
    gap: 8px !important;
  }
  .qcx-subscribe-card .qcx-sc-btn {
    flex: none !important;
    width: 100% !important;
    min-width: 0 !important;
    min-height: 42px !important;
    padding: 0 12px !important;
    font-size: 12px !important;
    justify-content: center;
  }
  .scroll--top {
    right: 12px !important;
    bottom: calc(12px + env(safe-area-inset-bottom, 0px)) !important;
  }
}
@media (min-width: 861px) {
  .qcx-hero-cta .qcx-cta-btn {
    min-width: 160px;
    justify-content: center;
  }
  .qcx-subscribe-card {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 20px !important;
  }
}
/* Card CTA hidden &#8212; title/thumbnail already links to the post. */
.qcx-card-cta,
.card-content .qcx-card-cta,
.all_posts .qcx-card-cta,
.qcx-rescue-blog .qcx-card-cta,
[data-page-item='multiple'] .card-content .qcx-card-cta,
.card-footer .theme-button,
.card-footer .button-wrapper {
  display: none !important;
  visibility: hidden !important;
  height: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: hidden !important;
  border: 0 !important;
}
.qcx-card-noimg {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 160px;
  color: var(--fg-dim);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: .08em;
  background: rgba(255,255,255,.03);
}
.qcx-subscribe-card .qcx-sc-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}
.qcx-subscribe-card .qcx-sc-form,
.qcx-subscribe-card .qcx-sc-input-wrap {
  display: none !important;
}
.qcx-sc-btn-outline,
a.qcx-sc-btn.qcx-sc-btn-outline,
.qcx-subscribe-card .qcx-sc-btn.qcx-sc-btn-outline {
  background: transparent !important;
  border: 1px solid rgba(232,239,233,.22) !important;
  color: #eafff4 !important;
  -webkit-text-fill-color: #eafff4 !important;
  box-shadow: none !important;
}
.qcx-sc-btn-outline:hover,
a.qcx-sc-btn.qcx-sc-btn-outline:hover,
.qcx-subscribe-card .qcx-sc-btn.qcx-sc-btn-outline:hover {
  background: rgba(28,36,32,.12) !important;
  border-color: #e8efe9 !important;
  color: #e8efe9 !important;
  -webkit-text-fill-color: #e8efe9 !important;
}
/* Subscribe primary &#8212; xanh &#273;en (match hero CTA); keep outline accent */
.qcx-subscribe-card .qcx-sc-btn:not(.qcx-sc-btn-outline),
a.qcx-sc-btn:not(.qcx-sc-btn-outline) {
  background: #141a16 !important;
  border: 1px solid #141a16 !important;
  color: #e8efe9 !important;
  -webkit-text-fill-color: #e8efe9 !important;
  box-shadow: none !important;
}
.qcx-subscribe-card .qcx-sc-btn:not(.qcx-sc-btn-outline):hover,
a.qcx-sc-btn:not(.qcx-sc-btn-outline):hover {
  background: #1c2420 !important;
  border-color: #e8efe9 !important;
  color: #f2f7f3 !important;
  -webkit-text-fill-color: #f2f7f3 !important;
  box-shadow: none !important;
  transform: none !important;
}
/* Custom floating CTA removed &#8212; mobile uses native tab bar. */
.qcx-mobile-cta { display: none !important; }
.qcx-404-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  justify-content: center;
  margin-top: 18px;
}
.qcx-404-actions a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 14px;
  border-radius: 10px;
  border: 1px solid rgba(28,36,32,.4);
  color: var(--accent);
  text-decoration: none;
  font-size: 12px;
}
.qcx-404-actions a:first-child {
  background: #141a16;
  color: #e8efe9;
  border-color: #141a16;
}
.qcx-rescue-status {
  grid-column: 1 / -1;
  color: var(--fg-dim);
  font: 400 13px/1.5 var(--mono);
  padding: 12px 4px 24px;
}
@keyframes qcxSkelShine {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}
@keyframes qcxFeedIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: none; }
}
.qcx-skel-card,
.qcx-skel-post {
  pointer-events: none;
  user-select: none;
}
.qcx-skel-media,
.qcx-skel-line,
.qcx-skel-block {
  display: block;
  border-radius: 8px;
  position: relative;
  overflow: hidden;
  background: rgba(255,255,255,.04);
}
.qcx-skel-media::after,
.qcx-skel-line::after,
.qcx-skel-block::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(90deg, transparent 0%, rgba(28,36,32,.12) 45%, transparent 90%);
  animation: qcxSkelShine 1.1s ease-in-out infinite;
}
.qcx-skel-media {
  width: 100%;
  aspect-ratio: 16 / 9;
  border-radius: 0;
}
.qcx-skel-line {
  height: 12px;
  margin: 10px 0 0;
}
.qcx-skel-w40 { width: 40%; }
.qcx-skel-w70 { width: 70%; }
.qcx-skel-w90 { width: 90%; }
.qcx-skel-post {
  padding: 8px 0 28px;
}
.qcx-skel-block {
  height: 28px;
  margin: 0 0 14px;
}
.qcx-skel-block.qcx-skel-w40 { height: 14px; width: 32%; }
.qcx-skel-block.qcx-skel-body {
  height: 180px;
  margin-top: 18px;
  border-radius: 12px;
}
.qcx-rescue-blog.qcx-feed-in .card,
.qcx-rescue-blog.qcx-feed-in .post-item {
  animation: qcxFeedIn .38s cubic-bezier(.2,.7,.2,1) both;
}
.qcx-rescue-blog.qcx-feed-in .col-md-4:nth-child(1) .card { animation-delay: .02s; }
.qcx-rescue-blog.qcx-feed-in .col-md-4:nth-child(2) .card { animation-delay: .07s; }
.qcx-rescue-blog.qcx-feed-in .col-md-4:nth-child(3) .card { animation-delay: .12s; }
.qcx-rescue-blog.qcx-feed-in .col-md-4:nth-child(4) .card { animation-delay: .17s; }
.qcx-rescue-blog.qcx-feed-in .col-md-4:nth-child(5) .card { animation-delay: .22s; }
.qcx-rescue-blog.qcx-feed-in .col-md-4:nth-child(6) .card { animation-delay: .27s; }
@media (prefers-reduced-motion: reduce) {
  .qcx-skel-media,
  .qcx-skel-line,
  .qcx-skel-block,
  .qcx-rescue-blog.qcx-feed-in .card,
  .qcx-rescue-blog.qcx-feed-in .post-item {
    animation: none !important;
  }
}
.qcx-pager {
