}
.qcx-rescue-single .the-article {
  max-width: none;
  width: 100%;
  margin: 0 auto;
  padding: 12px 0 40px;
}
.qcx-rescue-single .post-title {
  color: var(--fg) !important;
  background: none !important;
  -webkit-background-clip: unset !important;
