          if(load_analytic==0){
            load_analytic=1
            appendChildHead('https://www.googletagmanager.com/gtag/js?id='+data.blog.analyticsAccountNumber,'js')
            window.dataLayer=window.dataLayer||[]
            function gtag(){dataLayer.push(arguments)}
