(function(){
  function qcxFixAriaHidden(){
    try{
      var els=document.querySelectorAll('[aria-hidden="true"]');
      for(var i=0;i<els.length;i++){
        var el=els[i];
        if(el.getAttribute('tabindex')==='0')el.setAttribute('tabindex','-1');
        var kids=el.querySelectorAll('[tabindex="0"],a,button,input,select,textarea');
        for(var j=0;j<kids.length;j++){kids[j].setAttribute('tabindex','-1');}
      }
    }catch(e){}
  }
  document.addEventListener('DOMContentLoaded',qcxFixAriaHidden,{once:true});
  window.addEventListener('load',qcxFixAriaHidden,{once:true});
  setTimeout(qcxFixAriaHidden,500);
  setTimeout(qcxFixAriaHidden,2000);
  window.__qcxFixAriaHidden=qcxFixAriaHidden;
})();
