/* QCX Ultra-clean Copy Icon Button for Terminal & Code blocks (PC & Mobile) */
(function() {
  var copySvg = '<svg class="qcx-copy-svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>';
  var checkSvg = '<svg class="qcx-check-svg" width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#00ff9c" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="20 6 9 17 4 12"></polyline></svg>';

  function deduplicateCopyButtons() {
    var strayBtns = document.querySelectorAll('pre > button, .mac-frame-content button, .mac-frame-content .qcx-copy-btn');
    for (var s = 0; s < strayBtns.length; s++) {
      try { strayBtns[s].parentNode.removeChild(strayBtns[s]); } catch (e) {}
    }
    var codeWraps = document.querySelectorAll('.qcx-code-wrap');
    for (var cw = 0; cw < codeWraps.length; cw++) {
      if (codeWraps[cw].querySelector('.mac-frame')) {
        var ch = codeWraps[cw].children;
        for (var ci = ch.length - 1; ci >= 0; ci--) {
          if (ch[ci].tagName === 'BUTTON' || (ch[ci].classList && ch[ci].classList.contains('qcx-copy-btn'))) {
            try { codeWraps[cw].removeChild(ch[ci]); } catch (e) {}
          }
        }
      }
    }
    var headers = document.querySelectorAll('.mac-frame-header');
    for (var h = 0; h < headers.length; h++) {
      var hBtns = headers[h].querySelectorAll('button, .qcx-copy-btn');
      if (hBtns.length > 0 && !hBtns[0].querySelector('.qcx-copy-svg')) {
        hBtns[0].className = 'qcx-copy-btn';
        hBtns[0].innerHTML = copySvg + checkSvg;
      }
      for (var bi = 1; bi < hBtns.length; bi++) {
        try { hBtns[bi].parentNode.removeChild(hBtns[bi]); } catch (e) {}
      }
    }
    var wraps = document.querySelectorAll('.qcx-code-wrap, .mac-frame');
    for (var w = 0; w < wraps.length; w++) {
      var wBtns = wraps[w].querySelectorAll('.qcx-copy-btn');
      for (var wi = 1; wi < wBtns.length; wi++) {
        try { wBtns[wi].parentNode.removeChild(wBtns[wi]); } catch (e) {}
      }
    }
  }

  function initCopyButtons() {
    if (typeof qcxBootMacFrames === 'function') {
      try { qcxBootMacFrames(); } catch (e) {}
    }
    deduplicateCopyButtons();
    var pres = document.querySelectorAll('.post-body pre, article pre, pre');
    pres.forEach(function(pre) {
      var frame = pre.closest ? pre.closest('.mac-frame') : null;
      var header = frame ? frame.querySelector('.mac-frame-header') : null;
      if (header && header.querySelector('.qcx-copy-btn')) {
        pre.setAttribute('data-qcx-copy-ready', '1');
        pre.setAttribute('data-copy-ready', 'true');
        return;
      }
      var wrap = pre.closest ? pre.closest('.qcx-code-wrap') : null;
      if (!frame && wrap && wrap.querySelector('button, .qcx-copy-btn, [class*=copy]')) {
        pre.setAttribute('data-qcx-copy-ready', '1');
        pre.setAttribute('data-copy-ready', 'true');
        return;
      }
      pre.setAttribute('data-qcx-copy-ready', '1');
      pre.setAttribute('data-copy-ready', 'true');

      var btn = document.createElement('button');
      btn.type = 'button';
      btn.className = 'qcx-copy-btn';
      btn.setAttribute('aria-label', 'Sao ch\u00e9p m\u00e3');
      btn.setAttribute('title', 'Sao ch\u00e9p m\u00e3');
      btn.innerHTML = copySvg + checkSvg + '<span class="qcx-copy-txt">Sao ch\u00e9p</span>';

      if (header) {
        /* btn goes into header bar, right of mac-dots */
        header.appendChild(btn);
      } else {
        if (!wrap) {
          wrap = document.createElement('div');
          wrap.className = 'qcx-code-wrap';
          pre.parentNode.insertBefore(wrap, pre);
          wrap.appendChild(pre);
        }
        wrap.appendChild(btn);
      }

      btn.addEventListener('click', function(e) {
        e.preventDefault();
        var codeEl = pre.querySelector('code') || pre;
        var text = (codeEl.innerText || codeEl.textContent || '').trim();
        var copyFn = (navigator.clipboard && navigator.clipboard.writeText) ?
          navigator.clipboard.writeText(text) :
          new Promise(function(resolve, reject) {
            var ta = document.createElement('textarea');
            ta.value = text;
            ta.style.position = 'fixed';
            ta.style.opacity = '0';
            document.body.appendChild(ta);
            ta.select();
            document.execCommand('copy') ? resolve() : reject();
            document.body.removeChild(ta);
          });

        copyFn.then(function() {
          btn.classList.add('copied');
          var txt = btn.querySelector('.qcx-copy-txt');
          if (txt) txt.textContent = '\u0110\u00e3 ch\u00e9p';
          setTimeout(function() {
            btn.classList.remove('copied');
            if (txt) txt.textContent = 'Sao ch\u00e9p';
          }, 1800);
        }).catch(function() {
          var txt = btn.querySelector('.qcx-copy-txt');
          if (txt) txt.textContent = 'L\u1ed7i';
          setTimeout(function() {
            if (txt) txt.textContent = 'Sao ch\u00e9p';
          }, 1800);
        });
      });
    });
    deduplicateCopyButtons();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initCopyButtons);
  } else {
    initCopyButtons();
  }
  window.addEventListener('load', initCopyButtons, {once:true});

  try {
    var obs = new MutationObserver(function() {
      deduplicateCopyButtons();
    });
    obs.observe(document.body || document.documentElement, { childList: true, subtree: true });
  } catch (ignore) {}
})();
