/* QCX Card Hero Fallback   pathname-matched (protocol/domain agnostic) + media$thumbnail & body img */
(function() {
  var isHome = !document.querySelector('.post-body.entry-content');
  if (!isHome) return;
  var fetchedMap = null;
  var fetchPromise = null;

  function normPath(u) {
    try {
      var a = document.createElement('a');
      a.href = String(u || '');
      return (a.pathname || '').replace(/\/+$/, '').toLowerCase();
    } catch (e) { return ''; }
  }

  function upgradeThumb(u) {
    if (!u || u.indexOf('data:image') !== -1) return '';
    return u
      .replace(/\/s\d+(-[a-z0-9-]+)?\//i, '/w720-h405-p-k-no-nu/')
      .replace(/=s\d+(-[a-z0-9-]+)?$/i, '=w720-h405-p-k-no-nu');
  }

  function getImageMap() {
    if (fetchedMap) return Promise.resolve(fetchedMap);
    if (fetchPromise) return fetchPromise;
    fetchPromise = fetch('/feeds/posts/default?alt=json&max-results=60&orderby=published', { credentials: 'same-origin' })
      .then(function(r) { return r.json(); })
      .then(function(data) {
        var entries = (data.feed && data.feed.entry) || [];
        var map = {};
        entries.forEach(function(e) {
          var postPath = '';
          (e.link || []).forEach(function(l) {
            if (l.rel === 'alternate' && l.href) postPath = normPath(l.href);
          });
          if (!postPath) return;
          var thumb = (e['media$thumbnail'] && e['media$thumbnail'].url) ? upgradeThumb(e['media$thumbnail'].url) : '';
          if (!thumb) {
            var content = (e.content && e.content.$t) || (e.summary && e.summary.$t) || '';
            var m = content.match(/<img[^>]+src=["']([^"']+)["']/i);
            if (m && m[1] && m[1].indexOf('data:image') === -1) thumb = upgradeThumb(m[1]);
          }
          if (thumb) map[postPath] = thumb;
        });
        fetchedMap = map;
        return map;
      })
      .catch(function() { fetchedMap = {}; return {}; });
    return fetchPromise;
  }

  function applyImages(map) {
    document.querySelectorAll('.qcx-card-noimg').forEach(function(noimg) {
      var card = noimg.closest('article, li, .post-outer');
      if (!card) return;
      var link = card.querySelector('.card-content .title a[href], .card-header > a[href], a[href*=".html"]');
      if (!link) return;
      var postPath = normPath(link.getAttribute('href') || link.href);
      var imgUrl = map[postPath];
      if (!imgUrl) return;
      var img = document.createElement('img');
      img.src = imgUrl;
      img.alt = (link.getAttribute('title') || link.textContent || '').trim();
      img.className = 'qcx-card-media';
      img.loading = 'eager';
      img.decoding = 'async';
      img.width = 720;
      img.height = 405;
      img.style.cssText = 'position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover;z-index:2';
      noimg.replaceWith(img);
    });
  }

  function tryFix() {
    if (!document.querySelector('.qcx-card-noimg')) return;
    getImageMap().then(function(map) { map && applyImages(map); });
  }

  try {
    var debTimer;
    var obs = new MutationObserver(function() {
      clearTimeout(debTimer);
      debTimer = setTimeout(tryFix, 150);
    });
    obs.observe(document.documentElement, { childList: true, subtree: true });
  } catch (e) {}

  window.addEventListener('load', function() { setTimeout(tryFix, 300); setTimeout(tryFix, 1200); setTimeout(tryFix, 3000); });
  setTimeout(tryFix, 600);
  setTimeout(tryFix, 1800);
})();
