(function(){
  var rIC=window.requestIdleCallback||function(cb){return setTimeout(cb,120)};
  function qcxFixAriaHiddenTabindex(){
    document.querySelectorAll('[aria-hidden="true"]').forEach(function(el){
      el.querySelectorAll('a,button,input,select,textarea,[tabindex]').forEach(function(ch){ch.setAttribute('tabindex','-1')});
    });
  }
  function qcxOptimizeMobileBrandMark(){
    var imgs=document.querySelectorAll('.qcx-avatar img,.qcx-layout-avatar img,img.qcx-brand-raster');
    for(var i=0;i<imgs.length;i++){
      if(imgs[i].hasAttribute('srcset')){imgs[i].removeAttribute('srcset');}
    }
  }
  function qcxObserveFooterClearance(){
    if(!('IntersectionObserver' in window))return;
    var ft=document.querySelector('footer.footer');
    if(!ft)return;
    var io=new IntersectionObserver(function(entries){
      entries.forEach(function(en){
        if(en.isIntersecting)document.documentElement.setAttribute('data-at-footer','1');
        else document.documentElement.removeAttribute('data-at-footer');
      });
    },{threshold:0.05});
    io.observe(ft);
  }
  rIC(function(){qcxFixAriaHiddenTabindex();qcxOptimizeMobileBrandMark();qcxObserveFooterClearance();});
  document.addEventListener('DOMContentLoaded',function(){rIC(function(){qcxFixAriaHiddenTabindex();qcxOptimizeMobileBrandMark();qcxObserveFooterClearance();});},{once:true});
  window.addEventListener('load',function(){rIC(function(){qcxFixAriaHiddenTabindex();qcxOptimizeMobileBrandMark();});},{once:true});

  /*    MMO TEAM PayOS 3-Tier & Gmail Auth Role Engine    */
  var API_BASE='https://timkiem-store-api.kkymljnk.workers.dev';
