        if(bg)bg.innerHTML=roleBadgeHtml(r);
      }else{
        loginBtn.hidden=false;
        chip.hidden=true;
      }
    }
    var extraTriggers=document.querySelectorAll('[data-qcx-google-login]');
    for(var j=0;j<extraTriggers.length;j++){
      var trg=extraTriggers[j];
      if(!trg.getAttribute('data-qcx-bound')){
        trg.setAttribute('data-qcx-bound','1');
        trg.addEventListener('click',function(ev){
          ev.preventDefault();
          ev.stopPropagation();
          triggerGoogleSignIn(null);
        });
      }
    }
  }
  if(!window.__qcxRenderAuthSlots)window.__qcxRenderAuthSlots=renderAuthSlots;
  function enforceV18RoleFxOverride(){
    /* auth CSS owned by layout-rescue #qcx-gmail-auth-css — do not blank */
    if(!window.__qcxRenderAuthSlots)window.__qcxRenderAuthSlots=renderAuthSlots;
    window.__qcxTriggerGoogleSignIn=triggerGoogleSignIn;
  }
  enforceV18RoleFxOverride();
  setTimeout(enforceV18RoleFxOverride,180);
  setTimeout(enforceV18RoleFxOverride,800);
  window.addEventListener('load',function(){enforceV18RoleFxOverride();renderAuthSlots();},{once:true});

  function loadGsiScript(cb){
    if(window.google && window.google.accounts && window.google.accounts.oauth2){
      if(cb)cb();
      return;
    }
    if(gsiScriptLoading){
      if(cb)setTimeout(cb,450);
      return;
    }
    gsiScriptLoading=true;
    var s=document.createElement('script');
    s.src='https://accounts.google.com/gsi/client';
    s.async=true;
    s.defer=true;
    s.onload=function(){if(cb)cb();};
    (document.head||document.documentElement).appendChild(s);
  }

  function fetchAuthConfig(){
    loadLocalAuthCfg();
    return fetch(API_BASE+'/api/auth/config',{method:'GET'}).then(function(r){return r.json();}).then(function(res){
      if(res && res.googleClientId)googleClientId=String(res.googleClientId).trim();
      return googleClientId;
    }).catch(function(){return googleClientId||'';});
  }

  function buildClientAuthResponse(profile,recoverRes){
    loadLocalAuthCfg();
    var cur=readEnt();
    var email=String(profile.email||'').trim().toLowerCase();
    var rawName=String(profile.name||'').trim();
    var emailPrefix=email.split('@')[0]||'Member';
    if((!rawName || rawName.toLowerCase()===emailPrefix.toLowerCase()) && email==='kkymljnk@gmail.com')rawName='Nguy\u1ec5n V\u0103n C\u1ea7n';
    else if((!rawName || rawName.toLowerCase()===emailPrefix.toLowerCase()) && email==='superkhung@gmail.com')rawName='SuperKhung';
    var name=rawName||emailPrefix;
    var vipExp=(recoverRes && recoverRes.vipExpiresAt)||cur.vipExpiresAt||null;
    var itemsArr=(recoverRes && Array.isArray(recoverRes.unlockedItems))
      ?recoverRes.unlockedItems.slice()
      :Object.keys(cur.unlockedItems||{});
    var role=computeClientRole(email,vipExp,itemsArr);
    var bgHex=role==='admin'?'2b0907':(role==='vip'?'261c05':(role==='pro'?'061d2b':'0d261a'));
    var fgHex=role==='admin'?'ff6b6b':(role==='vip'?'ffd166':(role==='pro'?'38bdf8':'34e6a0'));
    var fallbackAv='https://ui-avatars.com/api/?name='+encodeURIComponent(name)+'&background='+bgHex+'&color='+fgHex+'&bold=true&size=96';
    var ownerAv='https://cdn.jsdelivr.net/gh/kkymljnk/timkiem-blogger-assets@v2026.11.19.80/images/avatars/kkymljnk-google.png';
    var pic=(email==='kkymljnk@gmail.com'||email==='superkhung@gmail.com')?ownerAv:(profile.picture||fallbackAv);
    var sess=(recoverRes && recoverRes.sessionToken)||cur.sessionToken||('qcx_gmail_'+encodeURIComponent(email));
    return {
      ok:true,
      sessionToken:sess,
      vipExpiresAt:vipExp,
      unlockedItems:itemsArr,
      user:{
        email:email,
        name:name,
        picture:pic,
        role:role,
        vipActive:!!(vipExp && new Date(vipExp).getTime()>Date.now()),
        vipUntil:vipExp?new Date(vipExp).getTime():0,
        items:itemsArr,
        itemCount:itemsArr.length
      }
    };
  }

  var SAVED_ACCS_KEY='qcx_saved_google_accounts_v1';
  function readSavedAccounts(){
    try{
      var arr=JSON.parse(localStorage.getItem(SAVED_ACCS_KEY)||'[]');
      return Array.isArray(arr)?arr:[];
    }catch(e){return [];}
  }
  function rememberSavedAccount(u){
    if(!u || !u.email)return;
    try{
      var arr=readSavedAccounts().filter(function(x){return x && x.email!==u.email;});
      arr.unshift({email:u.email,name:u.name||u.email.split('@')[0],picture:u.picture||'',role:u.role||'member'});
      localStorage.setItem(SAVED_ACCS_KEY,JSON.stringify(arr.slice(0,5)));
    }catch(e){}
  }

  function handleAuthSuccess(res){
    if(!res || !res.ok || !res.sessionToken)return;
    var merged=saveEnt(res);
    if(merged && merged.user)rememberSavedAccount(merged.user);
    var gm=document.getElementById('qcx-google-auth-modal');
    if(gm)gm.classList.remove('is-open');
    var cfg=getResourceConfig();
    if(cfg.mode==='vip' || cfg.mode==='item'){
      if(merged && merged.user && merged.user.role==='admin'){
        unlockDomWithDelivery({});
        pendingPayosCfgAfterLogin=null;
        return;
      }
      tryAutoDelivery(cfg).then(function(unlocked){
        if(!unlocked && pendingPayosCfgAfterLogin){
          var nextCfg=pendingPayosCfgAfterLogin;
          pendingPayosCfgAfterLogin=null;
          openPayosModal(nextCfg,false);
        }else{
          pendingPayosCfgAfterLogin=null;
        }
      });
    }else if(pendingPayosCfgAfterLogin){
      var nextCfg2=pendingPayosCfgAfterLogin;
      pendingPayosCfgAfterLogin=null;
      openPayosModal(nextCfg2,false);
    }
  }

  function authenticateGmailProfile(profile,accessToken,statusEl){
    loadLocalAuthCfg();
    var email=String((profile && profile.email)||'').trim().toLowerCase();
    var rawName=String((profile && profile.name)||'').trim();
    var name=rawName||(email==='kkymljnk@gmail.com'?'Nguy\u1ec5n V\u0103n C\u1ea7n':(email==='superkhung@gmail.com'?'SuperKhung':(email.split('@')[0]||'')));
    var payload=accessToken
      ?{accessToken:accessToken,fallbackProfile:{email:email,name:name,picture:profile&&profile.picture}}
      :{fallbackProfile:{email:email,name:name,picture:profile&&profile.picture}};
    return fetch(API_BASE+'/api/auth/google',{
      method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify(payload)
    }).then(function(r){return r.json();}).then(function(res){
      if(res && res.ok && res.sessionToken){
        if(isClientAdminEmail(email) && res.user)res.user.role='admin';
        handleAuthSuccess(res);
        return true;
      }
      return Promise.reject(new Error('FALLBACK'));
    }).catch(function(){
      return fetch(API_BASE+'/api/recover',{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({query:email,contact:email})
      }).then(function(r){return r.json();}).catch(function(){return null;}).then(function(rec){
        var built=buildClientAuthResponse({email:email,name:name,picture:profile&&profile.picture},rec && rec.ok?rec:null);
        handleAuthSuccess(built);
        return true;
      });
    });
  }

  function startGoogleOAuthPopup(statusEl){
    // Same-tab OAuth only — never initTokenClient / gsi/transform popup.
    if(typeof window.__qcxStartGoogleOAuthPopup==='function'){
      try{window.__qcxStartGoogleOAuthPopup(statusEl);return;}catch(eCdn){}
    }
    loadLocalAuthCfg();
    if(!googleClientId)googleClientId='94419988478-0os3sguo1jbe06ob9fi5vusb969vpmil.apps.googleusercontent.com';
    try{
      sessionStorage.setItem('qcx_oauth_return',location.href.split('#')[0]);
      sessionStorage.setItem('qcx_oauth_pending','1');
    }catch(eSs){}
    location.assign('https://accounts.google.com/o/oauth2/v2/auth?'+[
      'client_id='+encodeURIComponent(googleClientId),
      'redirect_uri='+encodeURIComponent(location.origin+'/'),
      'response_type=token',
      'scope='+encodeURIComponent('openid email profile'),
      'prompt=select_account',
      'include_granted_scopes=true',
      'state='+encodeURIComponent('qcx_oauth1')
    ].join('&'));
  }

