      html+='<button type="button" class="qcx-ud-btn" data-qcx-pick-email="'+a.email+'" data-qcx-pick-name="'+(a.name||'')+'" style="border:1px solid rgba(52,230,160,0.25);background:rgba(52,230,160,0.06);margin-bottom:6px;padding:8px 10px;border-radius:10px">' +
        '<img src="'+av+'" alt="" style="width:28px;height:28px;border-radius:50%;object-fit:cover;flex:0 0 auto"/>' +
        '<div style="flex:1;min-width:0;text-align:left"><div style="font-weight:700;color:#fff;font-size:12.5px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(a.name||a.email)+'</div><div style="font-size:11px;color:#8fb6a1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+a.email+'</div></div>' +
        '<span style="font-size:11px;color:#34e6a0;font-weight:700">&#8594;</span>' +
      '</button>';
    }
    wrap.innerHTML=html;
    var btns=wrap.querySelectorAll('[data-qcx-pick-email]');
    for(var j=0;j<btns.length;j++){
      btns[j].addEventListener('click',function(){
        var em=this.getAttribute('data-qcx-pick-email')||'';
        var nm=this.getAttribute('data-qcx-pick-name')||'';
        var st=document.getElementById('qcx-ga-status');
        if(st){st.classList.remove('is-err');st.textContent='\u0110ang \u0111\u0103ng nh\u1eadp '+em+'...';}
        authenticateGmailProfile({email:em,name:nm},'',st);
      });
    }
