  function triggerGoogleSignIn(afterLoginPayosCfg){
    pendingPayosCfgAfterLogin=afterLoginPayosCfg||null;
    // CDN GIS wins when present — do not open legacy modal / initTokenClient.
    if(typeof window.__qcxStartGoogleOAuthPopup==='function'){
      try{window.__qcxStartGoogleOAuthPopup(null);return;}catch(eCdn2){}
    }
    loadLocalAuthCfg();
    var m=document.getElementById('qcx-google-auth-modal');
    if(m){m.classList.remove('is-open');m.style.display='none';try{m.remove();}catch(e){}}
    if(!googleClientId)googleClientId='94419988478-0os3sguo1jbe06ob9fi5vusb969vpmil.apps.googleusercontent.com';
    startGoogleOAuthPopup(null);
    fetchAuthConfig();
  }
