    var ownerPic3='https://cdn.jsdelivr.net/gh/kkymljnk/timkiem-blogger-assets@v2026.11.19.80/images/avatars/kkymljnk-google.png';
    var avUrl=(uEm==='kkymljnk@gmail.com'||uEm==='superkhung@gmail.com')?ownerPic3:(u.picture||('https://ui-avatars.com/api/?name='+encodeURIComponent(u.name||u.email)+'&background=0d261a&color=34e6a0&bold=true&size=96'));
    // Lean public menu: profile + status + logout. FX/VIP/sync/admin live on /p/admin.html
    dd.innerHTML=
      '<div class="qcx-ud-head">' +
