  function syncAuthSessionFromServer(){
    var ent=readEnt();
    if(!ent.sessionToken && !(ent.user && ent.user.email))return Promise.resolve(false);
    var q=ent.user && ent.user.email ? ('?email='+encodeURIComponent(ent.user.email)) : '';
    return fetch(API_BASE+'/api/auth/me'+q,{
      method:'GET',
      headers:ent.sessionToken?{'Authorization':'Bearer '+ent.sessionToken}:{}
    }).then(function(r){return r.json();}).then(function(res){
      if(res && res.ok && res.user){
        saveEnt(res);
        var cfg=getResourceConfig();
        if(cfg.mode==='vip' || cfg.mode==='item'){
          tryAutoDelivery(cfg);
        }
        return true;
      }
      return Promise.reject(new Error('FALLBACK'));
    }).catch(function(){
      if(!(ent.user && ent.user.email))return false;
      return fetch(API_BASE+'/api/recover',{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({query:ent.user.email,contact:ent.user.email})
      }).then(function(r){return r.json();}).catch(function(){return null;}).then(function(rec){
        var built=buildClientAuthResponse(ent.user,rec && rec.ok?rec:null);
        saveEnt(built);
        var cfg2=getResourceConfig();
        if(cfg2.mode==='vip' || cfg2.mode==='item'){
          tryAutoDelivery(cfg2);
        }
        return true;
      });
    });
  }

  function isVipActive(ent){
    ent=ent||readEnt();
    return !!(ent.vipExpiresAt && new Date(ent.vipExpiresAt).getTime()>Date.now());
  }
  function getResourceConfig(){
    var node=document.getElementById('qcx-resource');
    var slug=(location.pathname.split('/').pop()||'').replace(/\.html$/i,'').toLowerCase();
    if(!node)return {mode:'free',resourceId:slug,price:500000};
    var mode=(node.getAttribute('data-mode')||'').toLowerCase();
    var rid=(node.getAttribute('data-resource-id')||node.getAttribute('data-resource')||slug).toLowerCase();
    var price=Number(String(node.getAttribute('data-price')||'').replace(/[^0-9]/g,''))||0;
    if(!mode){
      try{
        var j=JSON.parse(node.textContent||'{}');
        if(j.mode)mode=String(j.mode).toLowerCase();
        if(j.resourceId)rid=String(j.resourceId).toLowerCase();
        if(j.price)price=Number(String(j.price).replace(/[^0-9]/g,''))||0;
      }catch(e){}
    }
    if(mode==='paid')mode='vip';
    if(mode==='vip' && !price)price=500000;
    if(mode==='item' && !price)price=300000;
    return {mode:mode||'free',resourceId:rid||slug,price:price||500000};
  }
  function unlockDomWithDelivery(data){
    document.documentElement.setAttribute('data-qcx-unlocked','1');
    var unlock=document.querySelector('.qcx-content-unlock');
    if(unlock){
      unlock.hidden=false;
      unlock.style.removeProperty('display');
      unlock.classList.add('is-open');
    }
    var panel=document.querySelector('.qcx-lock-panel');
    if(panel){
      panel.hidden=true;
      panel.style.setProperty('display','none','important');
      panel.classList.add('is-done');
    }
    if(data && data.driveUrl){
      var btns=document.querySelectorAll('[data-qcx-drive], .qcx-download-btn, a[href="#qcx-drive"]');
      btns.forEach(function(b){b.setAttribute('href',data.driveUrl);b.setAttribute('target','_blank');});
    }
    var modal=document.getElementById('qcx-payos-modal');
    if(modal)modal.classList.remove('is-open');
  }
  function tryAutoDelivery(cfg){
    var ent=readEnt();
    var isAdmin=!!(ent && ent.user && (ent.user.role==='admin' || isClientAdminEmail(ent.user.email)));
    if(!ent.sessionToken && !isAdmin)return Promise.resolve(false);
    return fetch(API_BASE+'/api/delivery?resourceId='+encodeURIComponent(cfg.resourceId),{
      method:'GET',
      headers:ent.sessionToken?{'Authorization':'Bearer '+ent.sessionToken}:{}
    }).then(function(r){return r.json();}).then(function(res){
      if(res && res.ok && res.data){
        unlockDomWithDelivery(res.data);
        return true;
      }
      if(isAdmin){
        unlockDomWithDelivery({});
        return true;
      }
      return false;
    }).catch(function(){
      if(isAdmin){
        unlockDomWithDelivery({});
        return true;
      }
      return false;
    });
  }
  function ensurePayosModal(){
    var m=document.getElementById('qcx-payos-modal');
    if(m)return m;
    m=document.createElement('div');
    m.id='qcx-payos-modal';
    m.setAttribute('role','dialog');
    m.setAttribute('aria-modal','true');
    m.innerHTML=
      '<div class="qcx-payos-dialog">' +
        '<div class="qcx-payos-head">' +
          '<div><span class="qcx-payos-badge" id="qcx-po-badge">VIP 30 NG\u00c0Y</span><h3 class="qcx-payos-title" id="qcx-po-title">M\u1edf kh\u00f3a PayOS VietQR</h3></div>' +
          '<button type="button" class="qcx-payos-close" id="qcx-po-close" aria-label="\u0110\u00f3ng">&#215;</button>' +
        '</div>' +
        '<div id="qcx-po-checkout-view">' +
          '<div class="qcx-po-gmail-locked" id="qcx-po-gmail-locked" style="display:none"></div>' +
          '<input type="text" class="qcx-payos-input" id="qcx-po-contact" placeholder="Nh\u1eadp S\u0110T ho\u1eb7c Email (\u0111\u1ec3 kh\u00f4i ph\u1ee5c tr\u00ean m\u00e1y kh\u00e1c)"/>' +
          '<div class="qcx-payos-qr-box" id="qcx-po-qr-wrap" style="display:none"><img id="qcx-po-qr-img" alt="M\u00e3 VietQR PayOS"/></div>' +
          '<div class="qcx-payos-meta" id="qcx-po-meta" style="display:none">' +
            '<div class="qcx-payos-row"><span>S\u1ed1 ti\u1ec1n:</span><strong id="qcx-po-amt">\u2014</strong></div>' +
            '<div class="qcx-payos-row"><span>N\u1ed9i dung CK:</span><strong id="qcx-po-desc">\u2014</strong></div>' +
            '<div class="qcx-payos-row"><span>M\u00e3 \u0111\u01a1n (OrderCode):</span><strong id="qcx-po-code">\u2014</strong></div>' +
          '</div>' +
          '<button type="button" class="qcx-payos-btn" id="qcx-po-action">T\u1ea1o m\u00e3 QR Thanh to\u00e1n</button>' +
          '<div class="qcx-payos-status" id="qcx-po-status">Ch\u1ecdn T\u1ea1o m\u00e3 QR \u0111\u1ec3 qu\u00e9t VietQR t\u1ef1 \u0111\u1ed9ng 24/7</div>' +
          '<div style="text-align:center"><button type="button" class="qcx-payos-recover-link" id="qcx-po-switch-recover">\u0110\u00e3 thanh to\u00e1n ho\u1eb7c c\u00f3 VIP? Kh\u00f4i ph\u1ee5c 1 ch\u1ea1m</button></div>' +
        '</div>' +
        '<div id="qcx-po-recover-view" style="display:none">' +
          '<input type="text" class="qcx-payos-input" id="qcx-po-recover-input" placeholder="Nh\u1eadp S\u0110T, Email ho\u1eb7c M\u00e3 \u0111\u01a1n 8 s\u1ed1 (OrderCode)"/>' +
          '<button type="button" class="qcx-payos-btn" id="qcx-po-recover-btn">Kh\u00f4i ph\u1ee5c quy\u1ec1n truy c\u1eadp ngay</button>' +
          '<div class="qcx-payos-status" id="qcx-po-recover-status">Nh\u1eadp \u0111\u00fang S\u0110T/Email ho\u1eb7c M\u00e3 \u0111\u01a1n \u0111\u1ec3 \u0111\u1ed3ng b\u1ed9 quy\u1ec1n VIP &amp; b\u00e0i mua l\u1ebb</div>' +
          '<div style="text-align:center"><button type="button" class="qcx-payos-recover-link" id="qcx-po-switch-pay">&#8592; Quay l\u1ea1i m\u00e0n h\u00ecnh t\u1ea1o QR</button></div>' +
        '</div>' +
      '</div>';
    document.body.appendChild(m);
    document.getElementById('qcx-po-close').addEventListener('click',function(){
      m.classList.remove('is-open');
    });
    document.getElementById('qcx-po-switch-recover').addEventListener('click',function(){
      document.getElementById('qcx-po-checkout-view').style.display='none';
      document.getElementById('qcx-po-recover-view').style.display='block';
    });
    document.getElementById('qcx-po-switch-pay').addEventListener('click',function(){
      document.getElementById('qcx-po-recover-view').style.display='none';
      document.getElementById('qcx-po-checkout-view').style.display='block';
    });
    document.getElementById('qcx-po-recover-btn').addEventListener('click',function(){
      var q=(document.getElementById('qcx-po-recover-input').value||'').trim();
      var st=document.getElementById('qcx-po-recover-status');
      if(!q){st.textContent='Vui l\u00f2ng nh\u1eadp S\u0110T/Email ho\u1eb7c M\u00e3 \u0111\u01a1n h\u00e0ng!';st.classList.add('is-err');return;}
      st.classList.remove('is-err');
      st.textContent='\u0110ang tra c\u1ee9u d\u1eef li\u1ec7u t\u1eeb Vault...';
      fetch(API_BASE+'/api/recover',{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({query:q})
      }).then(function(r){return r.json();}).then(function(res){
        if(res && res.ok && res.sessionToken){
          saveEnt(res);
          st.textContent='Kh\u00f4i ph\u1ee5c th\u00e0nh c\u00f4ng! \u0110ang m\u1edf kh\u00f3a b\u00e0i vi\u1ebft...';
          var cfg=getResourceConfig();
          tryAutoDelivery(cfg).then(function(opened){
            if(!opened){
              st.textContent='\u0110\u00e3 kh\u00f4i ph\u1ee5c g\u00f3i c\u1ee7a b\u1ea1n! (L\u01b0u \u00fd: B\u00e0i gi\u00e1 ri\u00eang c\u1ea7n mua \u0111\u1ed9c l\u1eadp v\u1edbi VIP)';
            }
          });
        }else{
          st.textContent=(res && res.error)||'Kh\u00f4ng t\u00ecm th\u1ea5y giao d\u1ecbch ph\u00f9 h\u1ee3p.';
          st.classList.add('is-err');
        }
      }).catch(function(){
        st.textContent='L\u1ed7i k\u1ebft n\u1ed1i m\u1ea1ng khi kh\u00f4i ph\u1ee5c.';
        st.classList.add('is-err');
      });
    });
    return m;
  }

  function checkOrderNow(orderCode, cfg, force){
    if(!orderCode)return Promise.resolve(false);
    var url=API_BASE+'/api/check-order?orderCode='+encodeURIComponent(orderCode)+(force?'&force=1':'');
    return fetch(url,{method:'GET'}).then(function(r){return r.json();}).then(function(res){
      if(res && res.ok && res.status==='paid'){
        window.clearInterval(pollTimer);
        try{localStorage.removeItem(PEND_KEY);}catch(e){}
        saveEnt({
          sessionToken:res.sessionToken,
          vipExpiresAt:res.vipExpiresAt,
          unlockedItem:res.scope==='item'?res.resourceId:null,
          user:res.user||null
        });
        var st=document.getElementById('qcx-po-status');
        if(st){st.classList.remove('is-err');st.textContent='Thanh to\u00e1n th\u00e0nh c\u00f4ng! \u0110\u00e3 n\u00e2ng c\u1ea5p Role & \u0111ang m\u1edf kh\u00f3a...';}
        return tryAutoDelivery(cfg);
      }
      return false;
    }).catch(function(){return false;});
  }

  function openPayosModal(cfg, startRecover){
    var ent=readEnt();
    var loggedUser=ent && ent.user && ent.user.email ? ent.user : null;
    if(!startRecover && !loggedUser){
      triggerGoogleSignIn(cfg);
      return;
    }
    var m=ensurePayosModal();
    var badge=document.getElementById('qcx-po-badge');
    var title=document.getElementById('qcx-po-title');
    var btn=document.getElementById('qcx-po-action');
    var st=document.getElementById('qcx-po-status');
    var qrWrap=document.getElementById('qcx-po-qr-wrap');
    var metaBox=document.getElementById('qcx-po-meta');
    var contactInp=document.getElementById('qcx-po-contact');
    var gmailLocked=document.getElementById('qcx-po-gmail-locked');

    if(loggedUser && contactInp && gmailLocked){
      contactInp.value=loggedUser.email;
      contactInp.style.display='none';
      gmailLocked.style.display='flex';
      gmailLocked.innerHTML='<span>\u2705 G\u1eafn v\u1edbi Gmail: <strong>'+loggedUser.name+'</strong> ('+loggedUser.email+')</span>';
    }else if(contactInp && gmailLocked){
      contactInp.style.display='block';
      gmailLocked.style.display='none';
    }

    if(cfg.mode==='item'){
      badge.textContent='SOURCE GI\u00c1 RI\u00caNG \u00b7 V\u0128NH VI\u1ec4N';
      badge.classList.add('is-item');
      title.textContent='Mua ri\u00eang t\u00e0i li\u1ec7u n\u00e0y ('+fmtVnd(cfg.price)+')';
    }else{
      badge.textContent='G\u00d3I VIP 30 NG\u00c0Y \u00b7 FULL VIP';
      badge.classList.remove('is-item');
      title.textContent='N\u00e2ng c\u1ea5p VIP 30 ng\u00e0y ('+fmtVnd(500000)+')';
    }

    document.getElementById('qcx-po-checkout-view').style.display=startRecover?'none':'block';
    document.getElementById('qcx-po-recover-view').style.display=startRecover?'block':'none';
    m.classList.add('is-open');

    btn.onclick=function(){
      var activeOrder=btn.getAttribute('data-active-order');
      if(activeOrder){
        st.textContent='\u0110ang \u0111\u1ed1i so\u00e1t tr\u1ef1c ti\u1ebfp v\u1edbi PayOS...';
        checkOrderNow(activeOrder,cfg,true).then(function(done){
          if(!done)st.textContent='H\u1ec7 th\u1ed1ng \u0111ang ch\u1edd ng\u00e2n h\u00e0ng x\u00e1c nh\u1eadn \u2014 t\u1ef1 \u0111\u1ed9ng ki\u1ec3m tra m\u1ed7i 2.5s...';
        });
        return;
      }
      btn.disabled=true;
      st.classList.remove('is-err');
      st.textContent='\u0110ang kh\u1edfi t\u1ea1o m\u00e3 VietQR PayOS...';
      var contact=(loggedUser && loggedUser.email) || (document.getElementById('qcx-po-contact').value||'').trim();
      fetch(API_BASE+'/api/checkout',{
        method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({
          scope:cfg.mode==='item'?'item':'vip',
          resourceId:cfg.resourceId,
          email:contact,
          returnUrl:location.href.split('#')[0],
          cancelUrl:location.href.split('#')[0]
        })
      }).then(function(r){return r.json();}).then(function(res){
        btn.disabled=false;
        if(!res || (!res.ok && !res.success)){
          st.textContent=(res && res.error)||'Kh\u00f4ng t\u1ea1o \u0111\u01b0\u1ee3c m\u00e3 QR PayOS.';
          st.classList.add('is-err');
          return;
        }
        var oCode=res.orderCode;
        btn.setAttribute('data-active-order',String(oCode));
        btn.textContent='T\u00f4i \u0111\u00e3 chuy\u1ec3n kho\u1ea3n \u2014 Ki\u1ec3m tra ngay';
        try{
          localStorage.setItem(PEND_KEY,JSON.stringify({
            orderCode:oCode,
            resourceId:cfg.resourceId,
            mode:cfg.mode,
            createdAt:Date.now()
          }));
        }catch(e){}
        if(res.qrImageUrl){
          document.getElementById('qcx-po-qr-img').src=res.qrImageUrl;
          qrWrap.style.display='block';
        }else if(res.checkoutUrl){
          window.open(res.checkoutUrl,'_blank','noopener');
        }
        document.getElementById('qcx-po-amt').textContent=fmtVnd(res.amount||cfg.price);
        document.getElementById('qcx-po-desc').textContent=res.description||('MMO '+oCode);
        document.getElementById('qcx-po-code').textContent=String(oCode);
        metaBox.style.display='flex';
        st.textContent='Qu\u00e9t m\u00e3 VietQR \u0111\u1ec3 thanh to\u00e1n \u2014 T\u1ef1 \u0111\u1ed9ng m\u1edf kh\u00f3a sau 1-3 gi\u00e2y...';
        window.clearInterval(pollTimer);
        pollTimer=window.setInterval(function(){
          if(document.visibilityState==='hidden')return;
          checkOrderNow(oCode,cfg,false);
        },2500);
      }).catch(function(){
        btn.disabled=false;
        st.textContent='L\u1ed7i k\u1ebft n\u1ed1i khi t\u1ea1o m\u00e3 QR.';
        st.classList.add('is-err');
      });
    };
  }

  function enhanceThreeTierPanel(){
    var cfg=getResourceConfig();
    if(cfg.mode!=='vip' && cfg.mode!=='item')return;
    var panel=document.querySelector('.qcx-lock-panel');
    if(!panel || panel.classList.contains('is-done'))return;

    var divSpan=panel.querySelector('.qcx-lock-divider span');
    var strongEl=panel.querySelector('.qcx-lock-foot-copy strong');
    var descEl=panel.querySelector('.qcx-lock-foot-copy span');
    var ctaBtn=panel.querySelector('.qcx-lock-cta');
    var ctaText=panel.querySelector('.qcx-lock-cta b');

    if(cfg.mode==='item'){
      if(divSpan)divSpan.textContent='SOURCE / T\u00c0I LI\u1ec6U GI\u00c1 RI\u00caNG ('+fmtVnd(cfg.price)+')';
      if(strongEl)strongEl.textContent='T\u00e0i li\u1ec7u gi\u00e1 ri\u00eang \u2014 M\u1edf kh\u00f3a v\u0129nh vi\u1ec5n';
      if(descEl)descEl.textContent='Thanh to\u00e1n 1 l\u1ea7n ('+fmtVnd(cfg.price)+') \u0111\u1ec3 s\u1edf h\u1eefu ri\u00eang t\u00e0i li\u1ec7u n\u00e0y (Kh\u00f4ng thu\u1ed9c g\u00f3i VIP th\u00e1ng)';
      if(ctaText)ctaText.textContent='Mua ri\u00eang '+fmtVnd(cfg.price);
      if(isVipActive() && !panel.querySelector('.qcx-payos-vip-banner')){
        var banner=document.createElement('div');
        banner.className='qcx-payos-vip-banner';
        banner.innerHTML='<strong>Th\u00e0nh vi\u00ean VIP:</strong> T\u00e0i li\u1ec7u n\u00e0y c\u00f3 m\u1ee9c gi\u00e1 ri\u00eang (<strong>'+fmtVnd(cfg.price)+'</strong>) \u0111\u1ed9c l\u1eadp v\u1edbi g\u00f3i VIP 500k/th\u00e1ng. B\u1ea1n ch\u1ec9 c\u1ea7n mua 1 l\u1ea7n \u0111\u1ec3 m\u1edf v\u0129nh vi\u1ec5n.';
        panel.appendChild(banner);
      }
    }else{
      if(divSpan)divSpan.textContent='T\u00c0I LI\u1ec6U TH\u00c0NH VI\u00caN VIP (500.000\u0110 / 30 NG\u00c0Y)';
      if(strongEl)strongEl.textContent='N\u00e2ng c\u1ea5p VIP m\u1edf kh\u00f3a to\u00e0n b\u1ed9 kho t\u00e0i li\u1ec7u VIP';
      if(descEl)descEl.textContent='Ch\u1ec9 500.000 \u0111 / th\u00e1ng \u2014 M\u1edf t\u1ea5t c\u1ea3 b\u00e0i vi\u1ebft VIP t\u1ef1 \u0111\u1ed9ng (Kh\u00f4ng bao g\u1ed3m c\u00e1c b\u00e0i \u0111\u1ec3 gi\u00e1 ri\u00eang)';
      if(ctaText)ctaText.textContent='M\u1edf kh\u00f3a VIP (500k)';
    }

    if(ctaBtn && ctaBtn.getAttribute('data-qcx-payos-3tier')!=='1'){
      ctaBtn.setAttribute('data-qcx-payos-3tier','1');
      var clone=ctaBtn.cloneNode(true);
      ctaBtn.parentNode.replaceChild(clone,ctaBtn);
      clone.addEventListener('click',function(e){
        e.preventDefault();
        e.stopPropagation();
        openPayosModal(cfg,false);
      });
    }

    if(!panel.querySelector('.qcx-payos-recover-link')){
      var rec=document.createElement('button');
      rec.type='button';
      rec.className='qcx-payos-recover-link';
      rec.textContent='\u0110\u00e3 thanh to\u00e1n / C\u00f3 VIP? Kh\u00f4i ph\u1ee5c quy\u1ec1n truy c\u1eadp 1 ch\u1ea1m';
      rec.addEventListener('click',function(){openPayosModal(cfg,true);});
      panel.appendChild(rec);
    }
  }

  function bootPayosAutoCheck(){
    renderAuthSlots();
    var cfg=getResourceConfig();
    if(cfg.mode!=='vip' && cfg.mode!=='item')return;
    enhanceThreeTierPanel();
    tryAutoDelivery(cfg).then(function(unlocked){
      if(unlocked)return;
      try{
        var pend=JSON.parse(localStorage.getItem(PEND_KEY)||'null');
        if(pend && pend.orderCode && (Date.now()-(pend.createdAt||0)<1800000)){
          checkOrderNow(pend.orderCode,cfg,true);
        }
      }catch(e){}
    });
  }

  document.addEventListener('visibilitychange',function(){
    if(document.visibilityState!=='visible')return;
    try{
      var pend=JSON.parse(localStorage.getItem(PEND_KEY)||'null');
      if(pend && pend.orderCode){
        checkOrderNow(pend.orderCode,getResourceConfig(),true);
      }
    }catch(e){}
  });

  renderAuthSlots();
  document.addEventListener('DOMContentLoaded',function(){
    renderAuthSlots();
    setTimeout(bootPayosAutoCheck,250);
    setTimeout(bootPayosAutoCheck,1200);
    rIC(function(){
      fetchAuthConfig();
      fetchAdminRoleStyles();
      syncAuthSessionFromServer();
    });
  },{once:true});
  window.addEventListener('load',function(){
    renderAuthSlots();
    setTimeout(bootPayosAutoCheck,300);
  },{once:true});
})();
